<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue';
import {withBase} from 'vitepress';
import {hardware} from './hardware-map.mjs';
import {illustratedMaterial,studioExposure} from './board-materials.mjs';
const props=defineProps({id:String,index:Number,count:Number});
const host=ref(),error=ref(false);
let update=()=>{},dispose=()=>{},dead=false;
watch(()=>props.id,()=>update());
onMounted(async()=>{try{
 const T=await import('three');const [{GLTFLoader},{MeshoptDecoder},{RoomEnvironment}]=await Promise.all([import('three/addons/loaders/GLTFLoader.js'),import('meshoptimizer'),import('three/addons/environments/RoomEnvironment.js')]);if(dead)return;
 const renderer=new T.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(300,118);renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=studioExposure;host.value.appendChild(renderer.domElement);
 const scene=new T.Scene(),camera=new T.OrthographicCamera(-12,12,4.72,-4.72,.1,200);camera.up.set(0,0,1);camera.position.set(4,-16,20);camera.lookAt(0,0,0);
 const room=new RoomEnvironment(),pm=new T.PMREMGenerator(renderer),env=pm.fromScene(room,.04);scene.environment=env.texture;room.dispose();pm.dispose();scene.add(new T.HemisphereLight(0xffffff,0x56667a,1.1));const light=new T.DirectionalLight(0xfff4df,2);light.position.set(-10,-15,30);scene.add(light);
 const loader=new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);const [gltf,powerModels]=await Promise.all([loader.loadAsync(withBase('/hardware/osrcore-styled.glb')),loader.loadAsync(withBase('/hardware/power-parts.glb'))]);if(dead){renderer.dispose();env.dispose();return;}gltf.scene.scale.setScalar(1000);gltf.scene.updateMatrixWorld(true);
 let detail;
 const clean=()=>{if(detail){scene.remove(detail);detail.traverse(o=>{o.geometry?.dispose();o.material?.dispose()})}};
 update=()=>{clean();const part=hardware.find(h=>h.id===props.id);if(!part)return;detail=new T.Group();const cx=(part.position[0]/100-.5)*41,cy=(.5-part.position[1]/100)*60,vertical=['EX1','LDS','EX3'].includes(props.id),back=part.side==='back';const xt=part.kind==='xt30',sx=xt?3:vertical?3.0:props.count*1.25/2+2.1,sy=xt?6.7:vertical?props.count*1.25/2+2.0:2.4;
 if(xt){const source=powerModels.scene.getObjectByName(props.id);const model=source.clone(true);model.traverse(o=>{if(!o.isMesh)return;o.geometry=o.geometry.clone();o.material=illustratedMaterial(o.material,T);if(parseInt(o.material.name.replace('mtl',''),10)===3){o.material.color.set('#d5ae60');o.material.metalness=.8;o.material.roughness=.25;}});detail.add(model);}else {
 gltf.scene.traverse(o=>{if(!o.isMesh)return;const source=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();for(const key of ['position','normal']){const a=source.getAttribute(key);if(a){const values=new Float32Array(a.count*3);for(let j=0;j<a.count;j++){values[j*3]=a.getX(j);values[j*3+1]=a.getY(j);values[j*3+2]=a.getZ(j)}source.setAttribute(key,new T.BufferAttribute(values,3))}}source.applyMatrix4(o.matrixWorld);const p=source.attributes.position,n=source.attributes.normal,positions=[],normals=[];for(let i=0;i<p.count;i+=3){const x=(p.getX(i)+p.getX(i+1)+p.getX(i+2))/3,y=(p.getY(i)+p.getY(i+1)+p.getY(i+2))/3,z=(p.getZ(i)+p.getZ(i+1)+p.getZ(i+2))/3;if(Math.abs(x-cx)>sx||Math.abs(y-cy)>sy||(back?z>-.85:z<(xt?-.05:.85)))continue;if(!xt&&[0,1,2].some(j=>Math.abs(p.getX(i+j)-cx)>sx+.5||Math.abs(p.getY(i+j)-cy)>sy+.5))continue;for(let j=0;j<3;j++){positions.push(p.getX(i+j)-cx,p.getY(i+j)-cy,p.getZ(i+j));if(n)normals.push(n.getX(i+j),n.getY(i+j),n.getZ(i+j))}}source.dispose();if(!positions.length)return;const geom=new T.BufferGeometry();geom.setAttribute('position',new T.Float32BufferAttribute(positions,3));if(normals.length)geom.setAttribute('normal',new T.Float32BufferAttribute(normals,3));else geom.computeVertexNormals();const original=Array.isArray(o.material)?o.material[0]:o.material,m=illustratedMaterial(original,T);if(part.kind==='xt30'&&parseInt(m.name.replace('mtl',''),10)!==2){m.color.set('#22272c');m.metalness=0;m.roughness=.65;m.clearcoat=0;m.specularIntensity=.2;m.envMapIntensity=.4;}detail.add(new T.Mesh(geom,m))});
 }
 if(vertical||part.kind==='xt30')detail.rotation.z=-Math.PI/2;if(back){detail.rotation.x=Math.PI;detail.rotation.z=Math.PI;}scene.add(detail);detail.updateMatrixWorld(true);const box=new T.Box3().setFromObject(detail),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3());detail.position.sub(center);const span=Math.max(5,size.length()*.34);camera.top=span;camera.bottom=-span;camera.left=-span*300/118;camera.right=span*300/118;camera.updateProjectionMatrix();host.value.dataset.materials=JSON.stringify(detail.children.filter(o=>o.isMesh).map(o=>[o.material.name,o.geometry.attributes.position.count]));host.value.dataset.meshes=detail.children.length;host.value.dataset.bounds=JSON.stringify([box.min.toArray(),box.max.toArray()]);renderer.render(scene,camera);
 };
 dispose=()=>{clean();gltf.scene.traverse(o=>o.geometry?.dispose());env.dispose();renderer.dispose();renderer.domElement.remove()};update();
 }catch(e){error.value=true;dispose()}});
onUnmounted(()=>{dead=true;dispose()});
</script>
<template><div class="connector-preview" :class="{power:hardware.find(h=>h.id===id)?.kind==='xt30'}"><div ref="host" class="connector-render" role="img" :aria-label="id+' 独立三维端子'"><span v-if="error">{{id}} · {{count}} PIN</span></div></div></template>
<style scoped>.connector-preview{width:100%;max-width:360px;margin:8px auto 12px;background:radial-gradient(ellipse at 50% 58%,#e6edf2 0%,#f7f9fb 62%);border:1px solid #edf1f4;border-radius:12px;display:flex;flex-direction:column;align-items:center}.connector-render{height:118px;width:300px;max-width:100%;display:grid;place-items:center}.connector-render :deep(canvas){max-width:100%;height:auto!important;filter:drop-shadow(0 6px 5px #26384720)}.pin-leader{width:100%;height:18px;overflow:visible}.pin-leader path{fill:none;stroke:#2296ce;stroke-width:1.2;vector-effect:non-scaling-stroke}</style>
